package com.phoenix.business.service;

import java.io.ByteArrayInputStream;
import java.util.Base64;
import javax.imageio.ImageIO;

/** Accept only the bounded, square PNG generated by the existing crop UI. */
public final class MemberPhoto {
    private MemberPhoto() {}

    public static String validate(String value) {
        if (value.isBlank()) return null;
        String prefix = "data:image/png;base64,";
        try {
            if (!value.startsWith(prefix) || value.length() > 2_800_000) throw new IllegalArgumentException();
            byte[] bytes = Base64.getDecoder().decode(value.substring(prefix.length()));
            if (bytes.length > 2 * 1024 * 1024) throw new IllegalArgumentException();
            try (var input = ImageIO.createImageInputStream(new ByteArrayInputStream(bytes))) {
                var readers = ImageIO.getImageReaders(input);
                if (!readers.hasNext()) throw new IllegalArgumentException();
                var reader = readers.next();
                try {
                    reader.setInput(input);
                    if (!reader.getFormatName().equalsIgnoreCase("png") || reader.getWidth(0) != 512
                            || reader.getHeight(0) != 512 || reader.read(0) == null) throw new IllegalArgumentException();
                } finally { reader.dispose(); }
            }
            return prefix + Base64.getEncoder().encodeToString(bytes);
        } catch (Exception invalid) {
            throw new IllegalArgumentException("Choose and crop a PNG or JPEG profile photo before saving");
        }
    }
}
